variables.native_stops:
{% set n=namespace(commands=[]) %}
{% for L,t in targets.items() if not t.is_room %}
 {% set stop=namespace(needed=old.get(L,{}).get('effect') in ['Breathe','Colour loop']) %}
 {% for channel in ['brightness','color'] %}
  {% if t[channel].kind=='effect' and t.owners[channel].startswith('channels:native:') and t[channel].updated!=old_targets.get(L,{}).get(channel,{}).get('updated') %}{% set stop.needed=true %}{% endif %}
 {% endfor %}
 {% if stop.needed %}{% for E in catalog.members.get(L,[]) if is_state(E,'on') %}{% for effect in ['stop_colorloop','stop_effect'] %}
  {% set n.commands=n.commands+[{'topic':catalog.topics[E],'payload':{'effect':effect},'members':[E],'owners':[L],'group':false}] %}
 {% endfor %}{% endfor %}{% endif %}
{% endfor %}{{ n.commands }}

variables.timing_revision:
{# No clock/schedule expansion: only versions of the room's expiry dependencies. #}
{% if command in ['up','down'] and is_state('input_boolean.ls_ovr_next_block_on','on') %}
 {% set n=namespace(ids=['input_boolean.ls_ovr_next_block_on']) %}
 {% for scope in ['house',room] %}
  {% for block in ['day','cosy','night'] %}
   {% set n.ids=n.ids+['input_boolean.ls_'~scope~'_'~block~'_own_timing','input_datetime.ls_'~scope~'_'~block~'_start','input_datetime.ls_'~scope~'_'~block~'_weekend','input_number.ls_'~scope~'_'~block~'_fade'] %}
  {% endfor %}
 {% endfor %}
 {% set version=namespace(latest=0) %}
 {% for entity in n.ids if states[entity] is not none %}
  {% set version.latest=[version.latest,as_timestamp(states[entity].last_updated,0)]|max %}
 {% endfor %}
 {{ version.latest }}
{% else %}{{ 0 }}{% endif %}

variables.result:
{# A scale owner already has its coordinate. Advance it without rendering any lights. #}
{% set key='channels:'~source %}{% set record=overrides.get(key,{}) %}
{% set value=record.get('value',{}) %}
{% set brightness=value.get('channels',{}).get('brightness',{}) if value is mapping else {} %}
{% set n=namespace(ok=command in ['up','down'] and record.get('scope')=='room' and record.get('target')==room and brightness.get('kind')=='scale' and brightness.get('position') is number,result=none) %}
{% if n.ok and is_state('input_boolean.ls_ovr_next_block_on','on') %}
 {% set n.ok=value.get('remote_valid_until',0)>stamp and value.get('remote_timing_revision')==timing_revision %}
{% endif %}
{% if n.ok %}
 {% set own_stamp=brightness.get('updated',as_timestamp(record.get('when'),0)) %}
 {% for other,r in overrides.items() if other!=key and r is mapping %}
  {% set applies=(r.get('scope')=='room' and r.get('target')==room) or (r.get('scope')=='house' and r.get('target')=='house' and room not in label_areas('private_room')) %}
  {% set v=r.get('value',{}) %}
  {% if applies and v is mapping and v.get('channels') is mapping and 'brightness' in v.channels %}
   {% set candidate=v.channels.brightness %}
   {% set updated=candidate.get('updated',as_timestamp(r.get('when'),0)) if candidate is mapping else as_timestamp(r.get('when'),0) %}
   {# Conservative fallback for a newer claim, even if the resolver later rejects it. #}
   {% if updated is not number or updated>=own_stamp %}{% set n.ok=false %}{% endif %}
  {% endif %}
 {% endfor %}
{% endif %}
{% if n.ok %}
 {% set position=[-2,[2,brightness.position+(0.1 if command=='up' else -0.1)]|min]|max %}
 {% set claim={'kind':'scale','position':position,'updated':stamp} %}
 {% set n.result={'op':'set','records':[{'kind':'channels','key':key,'source':source,'scope':'room','target':room,'value':{'position':position,'channels':{'brightness':claim,'color':claim}}}],'via':'remote'} %}
{% endif %}
{{ n.result }}

{% set key='channels:'~source %}{% set old=overrides.get(key,{}) %}{% set value=old.get('value',{}) %}
{% set group=current.plan.resolved.targets.get('room:'~room,{}) %}
{% set anchors=current.plan.base.get('room:'~room,{}) %}
{% set n=namespace(result={'op':'noop'}) %}
{% if room and (group or command in ['toggle','reset','sara_toggle']) and command in ['up','down','left','right','toggle','reset','sara_toggle'] %}
 {% if command=='sara_toggle' %}
  {% set n.result={'op':'clear','keys':['mode:sara'],'via':'remote'} if 'mode:sara' in overrides else {'op':'set','records':[{'kind':'mode','target':'sara','value':'on'}],'via':'remote'} %}
 {% elif command=='toggle' %}
  {% set ids=namespace(v=[]) %}
  {% for L in catalog.members if area_id(L)==room %}{% set ids.v=ids.v+[L] %}{% endfor %}
  {% for L in (state_attr('sensor.ls_overrides','switch_ranges') or {}) if area_id(L)==room %}{% set ids.v=ids.v+[L] %}{% endfor %}
  {% set saved=(state_attr('sensor.ls_overrides','power') or {}).get(room) %}
  {% set on=not saved if saved is boolean else not (ids.v|select('is_state','on')|list|count>0) %}
  {% set n.result={'op':'power','area':room,'on':on,'targets':ids.v,'via':'remote'} %}
 {% elif command=='reset' %}{% set n.result={'op':'clear_room','area':room,'via':'remote'} %}
 {% else %}
  {% set delta=anchors.day.brightness-anchors.cosy.brightness %}
  {% set floor=[76.5,anchors.cosy.brightness]|min %}
  {% set slope=[0,delta,(anchors.cosy.brightness-floor)/2]|max %}
  {% if group.level>anchors.day.brightness and anchors.day.brightness<255 %}
   {% set seed=1+(group.level-anchors.day.brightness)/(255-anchors.day.brightness) %}
  {% elif group.level<anchors.cosy.brightness and slope>0 %}
   {% set seed=[-2,(group.level-anchors.cosy.brightness)/slope]|max %}
  {% else %}{% set seed=(group.level-anchors.cosy.brightness)/delta if delta>0 else 1 %}{% endif %}
  {% set position=value.get('position',seed) if group.owners.get('brightness')==key else seed %}
  {% set patch=namespace(v={},channels={}) %}
  {% if command in ['up','down'] %}
   {% set position=[-2,[2,position+(0.1 if command=='up' else -0.1)]|min]|max %}
   {% set claim={'kind':'scale','position':position,'updated':stamp} %}
   {% set brightness={'kind':'constant','value':group.level,'updated':stamp} if command=='down' and group.level<floor else claim %}
   {% set patch.v={'position':position,'channels':{'brightness':brightness,'color':claim}} %}
   {% set S=current.plan.get('schedule_details',{}).get(room,{}) %}
   {% set patch.v=dict(patch.v,remote_valid_until=S.get('next_fs',0),remote_timing_revision=timing_revision|default(0)) %}
  {% else %}
   {% set choices=['day','cosy','Candle'] + (catalog.effects.keys()|reject('eq','Candle')|list) %}
   {% set selected=value.get('selection',group.period) %}
   {% set index=choices.index(selected) if selected in choices else 0 %}
   {% set selected=choices[(index+(1 if command=='right' else -1)) % (choices|count)] %}
   {% if selected in ['day','cosy'] %}
    {% set position=1 if selected=='day' else 0 %}{% set claim={'kind':'scale','position':position,'updated':stamp} %}
    {% set patch.v={'selection':selected,'position':position,'period':selected,'period_updated':stamp,'channels':{'brightness':claim,'color':claim}} %}
   {% else %}
    {% for channel in catalog.effects[selected].channels %}{% set patch.channels=dict(patch.channels,**{channel:{'kind':'effect','effect':selected,'instance':source~':'~selected,'updated':stamp}}) %}{% endfor %}
    {% set patch.v={'selection':selected,'channels':patch.channels} %}
   {% endif %}
  {% endif %}
  {% if patch.v %}{% set n.result={'op':'set','records':[{'kind':'channels','key':key,'source':source,'scope':'room','target':room,'value':patch.v}],'via':'remote'} %}{% endif %}
 {% endif %}
{% endif %}
{{ n.result }}

variables.messages:
{% set targets = state_attr('sensor.effects_controller', 'targets') or {} %}
{% set assignments = state_attr('sensor.effects_controller', 'assignments') or {} %}
{% set ns = namespace(messages=[]) %}
{% for row in rows %}
 {% set source=row.source %}{% set proxy=row.proxy %}
 {% set available=states(source) in ['on','off'] %}
 {% if force|default(false) or available != (states(proxy) in ['on','off']) %}{% set ns.messages=ns.messages+[{'topic':row.topics.availability,'payload':'online' if available else 'offline'}] %}{% endif %}
 {% set profile=states(row.store)|from_json({}) if row.store else {} %}
 {% set fx=namespace(names=[],levels=[],colors=[]) %}
 {% for member in row.members %}
  {% set entry=targets.get(member,assignments.get(member,{})) %}
  {% if entry is mapping %}
   {% for channel in ['brightness','color'] %}
    {% set claim=entry.get(channel,{}) %}
    {% if claim is mapping and claim.get('kind')=='effect' and claim.get('effect') %}{% set fx.names=fx.names+[claim.effect] %}{% endif %}
   {% endfor %}
   {% if entry.get('effect') and entry.effect!='Normal light' %}{% set fx.names=fx.names+[entry.effect] %}{% endif %}
   {% if entry.get('level') is number %}{% set fx.levels=fx.levels+[entry.level] %}
   {% elif entry.get('brightness') is number %}{% set fx.levels=fx.levels+[entry.brightness] %}{% endif %}
   {% set color=entry.get('color',{}) %}
   {% if color is mapping and color.get('kind')=='constant' and color.get('value') is mapping %}{% set fx.colors=fx.colors+[color.value] %}{% endif %}
  {% endif %}
 {% endfor %}
 {% set unique_effects=fx.names|unique|list %}
 {% set effect=unique_effects[0] if unique_effects|count==1 else '' if unique_effects|count>1 else 'Normal light' %}
 {% if row.store %}{% set effect=profile.get('effect','Normal light') if profile.get('effect_channels',['brightness','color']) else 'Normal light' %}{% endif %}
 {% set power='ON' if is_state(source,'on') else 'OFF' %}
 {% set b=state_attr(source,'brightness') %}{% set k=state_attr(source,'color_temp_kelvin') %}{% set rgb=state_attr(source,'rgb_color') %}{% set mode=state_attr(source,'color_mode') %}
 {% set display=namespace(target=targets.get(source,{}),color={}) %}
 {% if not row.store and (row.members|count>1 or source not in row.members) %}
  {% set areas=row.members|map('area_id')|select|unique|list %}
  {% if areas|count==1 %}{% set display.target=targets.get('room:'~areas[0],{}) %}{% endif %}
 {% endif %}
 {% if not row.store %}
  {% if display.target.get('level') is number %}{% set b=display.target.level %}
  {% elif fx.levels|count==row.members|count and fx.levels %}{% set b=(fx.levels|sum/fx.levels|count)|round|int %}{% endif %}
  {% set color=display.target.get('color',{}) %}
  {% if color is mapping and color.get('kind')=='constant' %}{% set display.color=color.get('value',{}) %}
  {% elif not display.target and fx.colors|count==row.members|count and fx.colors %}
   {% set equal=namespace(ok=true) %}{% for c in fx.colors if c!=fx.colors[0] %}{% set equal.ok=false %}{% endfor %}
   {% if equal.ok %}{% set display.color=fx.colors[0] %}{% endif %}
  {% endif %}
  {% if 'kelvin' in display.color %}{% set mode='color_temp' %}{% set k=display.color.kelvin %}
  {% elif 'rgb' in display.color %}{% set mode='rgb' %}{% set rgb=display.color.rgb %}{% endif %}
 {% endif %}
 {% if available %}
  {% if force|default(false) or states(proxy)!=states(source) %}{% set ns.messages=ns.messages+[{'topic':row.topics.power,'payload':power}] %}{% endif %}
  {% if force|default(false) or state_attr(proxy,'effect')!=effect %}{% set ns.messages=ns.messages+[{'topic':row.topics.effect,'payload':effect}] %}{% endif %}
  {% if b is number and (force|default(false) or state_attr(proxy,'brightness')!=b|round|int) %}{% set ns.messages=ns.messages+[{'topic':row.topics.brightness,'payload':b|round|int|string}] %}{% endif %}
  {% if mode=='color_temp' and k is number and k>0 %}
   {% set mired=(1000000/k)|round|int %}{% set proxy_k=state_attr(proxy,'color_temp_kelvin')|float(0) %}{% set proxy_mired=(1000000/proxy_k)|round|int if proxy_k>0 else 0 %}
   {% if force|default(false) or state_attr(proxy,'color_mode')!='color_temp' or proxy_mired!=mired %}{% set ns.messages=ns.messages+[{'topic':row.topics.temperature,'payload':mired|string}] %}{% endif %}
  {% elif rgb is sequence and rgb|count==3 %}
   {% if force|default(false) or state_attr(proxy,'color_mode')!='rgb' or (state_attr(proxy,'rgb_color') or [])|list != rgb|list %}{% set ns.messages=ns.messages+[{'topic':row.topics.rgb,'payload':rgb|join(',')}] %}{% endif %}
  {% endif %}
 {% endif %}
{% endfor %}
{{ ns.messages }}

variables.result:
{% set d=trigger.event.data %}{% set op=d.get('op','set') %}
{% set prev=state_attr('sensor.ls_overrides','overrides') or {} %}
{% set n=namespace(o=prev,attributes={}) %}
{% if op=='clear_all' %}{% set n.o={} %}
{% elif op=='clear' %}{% set n.o=dict(prev.items()|rejectattr(0,'in',d.get('keys',[]))|list) %}
{% elif op=='clear_room' %}
 {% set keep=namespace(o={}) %}
 {% for key,r in prev.items() %}
  {% set matches=(r.get('scope')=='room' and r.target==d.area) or (r.get('scope')=='lamp' and area_id(r.target)==d.area) or (r.kind=='light' and area_id(r.target)==d.area) or (r.kind=='block' and r.target==d.area) %}
  {% if not matches %}{% set keep.o=dict(keep.o,**{key:r}) %}{% endif %}
 {% endfor %}{% set n.o=keep.o %}
{% elif op=='set' %}
 {% for r in d.get('records',[]) if r is mapping %}
  {% set key=r.get('key',r.kind~':'~r.get('source',r.target)) %}
  {% set old=n.o.get(key,{}) %}{% set value=r.get('value') %}
  {% if r.kind=='channels' and value is mapping %}
   {% set before=old.get('value',{}) %}{% set before=before if before is mapping else {} %}
   {% set merged=namespace(channels=before.get('channels',{})) %}
   {% for channel,claim in value.get('channels',{}).items() %}
    {% set previous=merged.channels.get(channel,{}) %}
    {% if claim.get('kind')=='effect' and 'underlying' not in claim %}
     {% set underlying=previous if previous.get('kind') in ['constant','scale'] else previous.get('underlying') %}
     {% if underlying is mapping %}{% set claim=dict(claim,underlying=underlying) %}{% endif %}
    {% endif %}
    {% set merged.channels=dict(merged.channels,**{channel:claim}) %}
   {% endfor %}
   {% set channels=merged.channels %}
   {% set value=dict(before,**value) %}{% set value=dict(value,channels=channels) %}
  {% endif %}
  {% set record=dict(r,value=value,when=now().isoformat(),created=old.get('created',old.get('when',now().isoformat())),who=d.get('who') or trigger.event.context.user_id,via=d.get('via')) %}
  {% set n.o=dict(n.o,**{key:record}) %}
 {% endfor %}
{% elif op=='power' %}
 {% set n.attributes={'power':dict(state_attr('sensor.ls_overrides','power') or {},**{d.area:d.on|bool})} %}
{% elif op=='range_set' %}
 {% set valid=d.get('profile') in ['bright','cosy'] or (d.get('profile')=='custom' and d.get('min') is number and d.get('max') is number and 0<=d.min<=d.max<=100) %}
 {% if valid %}{% set rule={'profile':d.profile} if d.profile!='custom' else {'profile':'custom','min':d.min,'max':d.max} %}{% set n.attributes={'switch_ranges':dict(state_attr('sensor.ls_overrides','switch_ranges') or {},**{d.entity:rule})} %}{% endif %}
{% elif op=='range_defaults' %}
 {% set ranges=d.get('ranges',{}) %}
 {% if ranges.get('bright') is sequence and ranges.get('cosy') is sequence and ranges.bright|count==2 and ranges.cosy|count==2 and 0<=ranges.bright[0]<=ranges.bright[1]<=100 and 0<=ranges.cosy[0]<=ranges.cosy[1]<=100 %}{% set n.attributes={'range_defaults':ranges} %}{% endif %}
{% endif %}
{% if d.get('via')=='remote' and d.get('source') and d.get('request_id') %}
 {% set n.attributes=dict(n.attributes,remote_ack=dict(state_attr('sensor.ls_overrides','remote_ack') or {},**{d.source:d.request_id})) %}
{% endif %}
{{ dict(n.attributes,overrides=n.o,last_via=d.get('via')) }}
